{tab==='Kelas & tahun'&&<section className="panel table-wrap"><table><thead><tr><th>Kelas</th><th>Unit</th><th>Tahun ajaran</th></tr></thead><tbody>{filtered('classes').map((c:any)=><tr key={c.id}><td>{c.name}</td><td>{c.unit}</td><td>{c.year}</td></tr>)}</tbody></table><p className="muted">Buat kelas terlebih dahulu sebelum mengimpor siswa atau menjadwalkan ujian.</p></section>}{tab==='Mata pelajaran'&&<section className="panel table-wrap"><table><thead><tr><th>Mata pelajaran</th><th>Unit</th><th>Paket soal</th></tr></thead><tbody>{filtered('subjects').sort((a:any,b:any)=>(a.unit+a.name).localeCompare(b.unit+b.name)).map((m:any)=><tr key={m.id}><td><strong>{m.name}</strong></td><td><Badge>{m.unit}</Badge></td><td>{data.banks.filter((b:any)=>b.unit===m.unit&&b.subject===m.name).length} paket</td></tr>)}</tbody></table>{!filtered('subjects').length&&<Empty text="Belum ada mata pelajaran pada unit ini."/>}</section>}
{tab==='Simulasi ujian'&&<><div className="toolbar"><select aria-label="Filter tingkat simulasi" value={form.simGradeFilter||''} onChange={e=>f('simGradeFilter',e.target.value)}><option value="">Semua tingkat</option>{['1','2','3','5','6'].map(g=><option key={g}>{g}</option>)}</select></div><p>Simulasi terpisah dari hasil ujian sekolah. Atur tingkat, soal, dan durasi melalui Detail Soal.</p><div className="bank-grid">{banks.filter((b:any)=>b.simulation&&(!form.simGradeFilter||b.grade===form.simGradeFilter)).map((b:any)=><section className="panel bank-card" key={b.id}><h2>{b.subject} – {b.grade||'Pilih tingkat'} {b.unit}</h2><p>{b.questions.length} soal · {b.duration||30} menit</p><button onClick={()=>{setForm(structuredClone(b));setModal('bank')}}>Detail Soal</button><button className="primary" disabled={busy} onClick={async()=>{const r=await run('startSimulation',{bankId:b.id},'Token simulasi dibuat');if(r){setForm({simulationToken:r.token});setModal('simulationToken')}}}>Generate token</button></section>)}</div></>}

{tab==='Jadwal ujian'&&<section className="panel table-wrap"><table><thead><tr>{['Ujian / Mata pelajaran','Unit & kelas','Jadwal (WIB)','Durasi','Status',''].map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{exams.map((e:any)=><tr key={e.id}><td><strong>{e.title}</strong><small>{e.subject}</small></td><td>{e.unit} · {e.className}</td><td>{date(e.start)}<small>s.d. {date(e.end)}</small></td><td>{e.duration} menit</td><td><Badge>{e.status}</Badge></td><td>{!teacher&&<button onClick={()=>{const {id,version,...copy}=e;setForm({...copy,title:e.title+' — Susulan',start:new Date(Date.now()+7*3600000).toISOString().slice(0,16),end:new Date(Date.now()+8*3600000).toISOString().slice(0,16)});setModal('exam')}}>Buat susulan</button>}<button className="text-btn" onClick={()=>{setTab('Token ujian');setSearch(e.title)}}>Token <ChevronRight size={14}/></button></td></tr>)}</tbody></table>{!exams.length&&<Empty text="Belum ada jadwal yang sesuai."/>}</section>}
