{tab==='Token ujian'&&<><div className="notice"><KeyRound size={19}/><div>Token dapat dilihat dan diunduh ulang oleh Admin Unit dan Super Admin. Mengunduh ulang tidak mengganti token atau mengubah jawaban siswa.</div></div><section className="panel table-wrap"><table><thead><tr><th>Ujian</th><th>Kelas</th><th>Peserta</th><th>Token dibuat</th><th/></tr></thead><tbody>{exams.map((e:any)=><tr key={e.id}><td><strong>{e.title}</strong><small>{e.subject}</small></td><td>{e.unit} · {e.className}</td><td>{data.students.filter((s:any)=>s.unit===e.unit&&s.className===e.className).length}</td><td>{data.attempts.filter((a:any)=>a.examId===e.id).length}</td><td><div className="token-actions">{data.attempts.some((a:any)=>a.examId===e.id)&&<><button disabled={busy} onClick={()=>viewTokens(e.id)}>Lihat token</button><button disabled={busy} onClick={()=>viewTokens(e.id,true)}><Download size={15}/>Download ulang</button></>}<button className="primary" disabled={busy} onClick={async()=>{const r=await run('generate',{examId:e.id},'Token selesai dibuat');if(r){setIssued(r.issued);setModal('tokens')}}}><KeyRound size={16}/>Generate token</button></div></td></tr>)}</tbody></table></section></>}
{(tab==='Monitoring'||tab==='Koreksi & nilai')&&<><div className="toolbar"><p className="muted">{attempts.length} peserta ujian · Monitoring diperbarui otomatis setiap 15 detik</p><div className="grow"/><button onClick={()=>csv('hasil-ujian.csv',attempts.filter((a:any)=>a.published).map((a:any)=>({Siswa:who(a.studentId),Ujian:examName(a.examId),Nilai:a.score,Status:'Dipublikasikan'})))}><Download size={16}/>Ekspor nilai terbit</button></div><section className="panel table-wrap"><table><thead><tr><th>Siswa</th><th>Ujian</th><th>Status</th><th>Terjawab</th><th>Koneksi / simpan terakhir</th><th>Nilai</th><th/></tr></thead><tbody>{attempts.map((a:any)=><tr key={a.id}><td><strong>{who(a.studentId)}</strong></td><td>{examName(a.examId)}</td><td><Badge>{a.published?'Dipublikasikan':a.status}</Badge></td><td>{Object.values(a.answers||{}).filter(Boolean).length} / {a.questions?.length||'–'}</td><td>{a.lastSeenAt?(Date.now()-a.lastSeenAt<90000?'Terhubung baru-baru ini':'Tidak ada kabar >90 detik'):'Belum terhubung'}<small>{a.lastSavedAt?date(a.lastSavedAt)+' WIB':'Belum ada jawaban tersimpan'}</small></td><td>{a.graded?a.score:'–'}</td><td>{a.status!=='Dikumpulkan'&&!teacher&&<button onClick={()=>{setForm({id:a.id,reason:'',minutes:10,action:'releaseSession'});setModal('supervise')}}>Tindakan pengawas</button>}{a.status!=='Dikumpulkan'&&!teacher&&<button className="text-btn" disabled={busy} onClick={async()=>{if(confirm('Ganti token siswa ini? Token lama tidak berlaku; jawaban dan waktu tetap.')){const r=await run('reissue',{id:a.id},'Token diganti');if(r){setIssued(r.issued);setModal('tokens')}}}}>Ganti token</button>}{a.status==='Dikumpulkan'&&!a.readOnly&&<button className="text-btn" onClick={()=>{setForm({...a,grades:{...a.grades}});setModal('grade')}}>{a.published?'Lihat hasil':'Koreksi'}<ChevronRight size={14}/></button>}</td></tr>)}</tbody></table>{!attempts.length&&<Empty text="Buat token untuk menyiapkan daftar peserta."/>}</section></>}
