useEffect(()=>{try{session.current=sessionStorage.getItem('cbt-device-session')||uid();sessionStorage.setItem('cbt-device-session',session.current);const saved=sessionStorage.getItem('cbt-active');if(saved&&!initialToken){const x=JSON.parse(saved),raw=localStorage.getItem('cbt-draft-'+x.id);if(raw){const d=JSON.parse(raw);setToken(x.token);attemptRef.current=d.attempt;setAttempt(d.attempt);latestAnswers.current=d.answers;setAnswers(d.answers);failed.current=d.pending||{};flagsRef.current=d.flags||[];setFlags(d.flags||[]);offset.current=d.offset||0;setStatus(Object.keys(failed.current).length?'Ada jawaban menunggu kirim':'Data terakhir dipulihkan');}}}catch{session.current=uid();setMessage('Penyimpanan perangkat tidak tersedia. Tetap buka halaman selama ujian.');}const t=setInterval(()=>setNow(Date.now()),1000);return()=>{clearInterval(t);lockRelease.current?.();}},[]);
useEffect(()=>{const guard=(e:BeforeUnloadEvent)=>{if(Object.keys(failed.current).length){e.preventDefault();e.returnValue=''}};window.addEventListener('beforeunload',guard);return()=>window.removeEventListener('beforeunload',guard)},[]);
async function acquireLock(id:string){if(lockRelease.current||!navigator.locks)return true;return new Promise<boolean>(resolve=>{navigator.locks.request('cbt-attempt-'+id,{ifAvailable:true},async lock=>{if(!lock){resolve(false);return;}await new Promise<void>(release=>{lockRelease.current=release;resolve(true);});}).catch(()=>resolve(false));});}
