useEffect(()=>{if(initialToken)void inspectToken()},[initialToken]);
async function enter(){setBusy(true);setMessage('');try{if(!await acquireLock(preview.id))throw Error('Ujian sudah terbuka di tab lain. Tutup tab ujian lainnya dahulu.');if(!identityChecked)throw Error('Centang konfirmasi identitas terlebih dahulu.');const a=await api('enter',{token,session:session.current,identityConfirmed:true});let draft:any=null;try{draft=JSON.parse(localStorage.getItem('cbt-draft-'+a.id)||'null')}catch{};failed.current=a.status==='Mengerjakan'?draft?.pending||{}:{};latestAnswers.current={...a.answers,...failed.current};flagsRef.current=draft?.flags||a.flags;setAnswers(latestAnswers.current);setFlags(flagsRef.current);apply(a);setPreview(null);try{sessionStorage.setItem('cbt-active',JSON.stringify({id:a.id,token}));}catch{}persist(a);await flush();}catch(e:any){setMessage(e.message)}finally{setBusy(false)}}
async function flush(){if(flushing.current||!attemptRef.current||attemptRef.current.status!=='Mengerjakan'||attemptRef.current.pausedAt)return;if(!await acquireLock(attemptRef.current.id)){setMessage('Ujian terbuka di tab lain.');return;}flushing.current=true;try{for(const key of Object.keys(failed.current)){const value=failed.current[key];setStatus('Menyimpan…');const a=await api('answer',{token,session:session.current,questionId:key,value,flags:flagsRef.current});apply(a);if(a.status!=='Mengerjakan'){setMessage('Waktu berakhir. Jawaban yang tiba setelah batas waktu tidak diterima.');break;}if(failed.current[key]===value)delete failed.current[key];persist(a);}setStatus(Object.keys(failed.current).length?'Menunggu pengiriman':'Tersimpan di server');if(!Object.keys(failed.current).length)setMessage('');}catch(e:any){setStatus('Tersimpan di perangkat — belum terkirim');setMessage(e.message);if(e.message.includes('dijeda')){try{apply(await api('heartbeat',{token,session:session.current}))}catch{}}}finally{flushing.current=false;persist();}}
function change(value:string,questionId=attempt.questions[index].id,nextFlags=flags){latestAnswers.current={...latestAnswers.current,[questionId]:value};failed.current[questionId]=value;flagsRef.current=nextFlags;setAnswers(latestAnswers.current);setFlags(nextFlags);persist();setStatus('Tersimpan di perangkat');void flush();}
useEffect(()=>{if(!attempt||attempt.status!=='Mengerjakan')return;const retry=()=>void flush();window.addEventListener('online',retry);const t=setInterval(retry,5000);const heartbeat=setInterval(async()=>{if(flushing.current||closing.current||Object.keys(failed.current).length)return;if(!await acquireLock(attempt.id))return;flushing.current=true;try{const a=await api('heartbeat',{token,session:session.current});apply(a);persist(a)}catch(e:any){setMessage(e.message);if(e.message.includes('dijeda'))apply({...attemptRef.current,pausedAt:Date.now(),remainingMs:Math.max(0,attemptRef.current.deadline-Date.now()-offset.current),serverNow:Date.now()+offset.current})}finally{flushing.current=false;}},30000);return()=>{clearInterval(t);clearInterval(heartbeat);window.removeEventListener('online',retry)}},[attempt?.id,attempt?.status,token]);
async function submit(auto=false){if(closing.current||flushing.current)return;if(auto&&Date.now()-lastAutoSubmit.current<5000)return;if(auto)lastAutoSubmit.current=Date.now();closing.current=true;setBusy(true);await flush();if(Object.keys(failed.current).length&&!auto){setMessage('Ada jawaban belum terkirim. Sambungkan internet dan tunggu tersimpan di server.');setBusy(false);closing.current=false;return}try{if(!auto){const issue=submissionIssue({...attemptRef.current,answers:latestAnswers.current,flags:flagsRef.current},Date.now()+offset.current);if(issue)throw Error(issue);}const a=await api('submit',{token,session:session.current});apply(a);setConfirmSubmit(false);if(Object.keys(failed.current).length)setMessage('Ujian ditutup sesuai batas waktu. Jawaban yang belum terkirim tidak masuk penilaian.');else{localStorage.removeItem('cbt-draft-'+a.id);sessionStorage.removeItem('cbt-active');}lockRelease.current?.();lockRelease.current=null;}catch(e:any){setMessage(e.message)}finally{setBusy(false);closing.current=false}}
