useEffect(()=>{if(attempt?.status==='Mengerjakan'&&remaining===0&&!attempt.pausedAt)submit(true)},[now,attempt?.status]);
const q:Question|undefined=attempt?.questions[index];const answerMode=q?.mode&&q.mode!=='TEKS'?q.mode:({'Matematika':'MATEMATIKA','Fisika':'FISIKA','Kimia':'KIMIA','Bahasa Arab':'ARAB'} as any)[attempt?.exam?.subject]||'TEKS';const answered=(attempt?.questions||[]).filter((q:Question)=>answeredQuestion(q,answers[q.id])).length;const submitIssue=attempt?.status==='Mengerjakan'?submissionIssue({...attempt,answers,flags},now+offset.current):'';
